import io
import json

import pandas as pd

DATA_DIR = "/app/dataset"
DAY_START = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
DAY_END = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")

# Error codes emitted by the loggers (not physical readings).
ERROR_CODES = {"-999.0", "888888.8"}

# Multipliers converting the sensor unit to kWh (energy) or kW (power).
UNIT_TO_K = {
    "wh": 1e-3,
    "kwh": 1.0,
    "mwh": 1e3,
    "btu": 1.0 / 3412.14163,
    "w": 1e-3,
    "kw": 1.0,
    "mw": 1e3,
}

TEMP_LIMIT_C = 85.0
SHUTDOWN_WINDOW = pd.Timedelta(minutes=45)

# Successfully completed maintenance windows (local civil time), from maintenance_notes.txt.
# Cancelled work (Sakura panel inspection on 2024-03-15) is intentionally not listed.
MAINTENANCE = {
    "sakura energy site": [("2024-03-16 08:00:00", "2024-03-16 12:00:00")],
    "vistula photovoltaics": [("2024-03-15 12:00:00", "2024-03-15 14:00:00")],
}


def read_text(path):
    raw = open(path, "rb").read()
    if raw[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return raw.decode("utf-16")
    if raw[:3] == b"\xef\xbb\xbf":
        return raw[3:].decode("utf-8")
    return raw.decode("utf-8")


def load_production(farm_id):
    lines = read_text(f"{DATA_DIR}/production_{farm_id}.csv").splitlines()
    start = next(i for i, l in enumerate(lines) if l.strip().lower().startswith("timestamp"))
    header = lines[start]
    sep = ";" if header.count(";") > header.count(",") else ","
    return pd.read_csv(
        io.StringIO("\n".join(lines[start:])), sep=sep, dtype=str, keep_default_na=False
    )


def to_number(value):
    s = str(value).strip()
    if s in ERROR_CODES:
        return float("nan")
    if "," in s:  # European format: '.' thousands separator, ',' decimal mark
        s = s.replace(".", "").replace(",", ".")
    try:
        return float(s)
    except ValueError:
        return float("nan")


def parse_timestamps(series):
    s = series.astype(str).str.strip()
    iso = pd.to_datetime(s, format="%Y-%m-%d %H:%M:%S", errors="coerce")
    eu = pd.to_datetime(s, format="%d.%m.%Y %H:%M:%S", errors="coerce")
    return iso.fillna(eu)


def farm_energy_kwh(farm_id, timezone, farm_key, calib):
    df = load_production(farm_id)
    ts_col = df.columns[0]
    value_col = calib["calibration_data"]["value_column_name"]
    offset = float(calib["calibration_data"]["calibration_offset"])
    unit = calib["sensor_info"]["unit"].strip().lower()
    reading_type = calib["sensor_info"]["reading_type"].strip().lower()

    df["ts_local"] = parse_timestamps(df[ts_col])
    df = df[df["ts_local"].notna()]

    # Corrupted transmissions are followed by a re-sent row with the same timestamp.
    df = df.drop_duplicates(subset=["ts_local"], keep="last").sort_values("ts_local")

    interval_h = df["ts_local"].diff().median() / pd.Timedelta(hours=1)

    df["value"] = df[value_col].map(to_number) - offset
    df["temp"] = df["inverter_temperature_C"].map(to_number)

    # Emergency shutdown: invalidate readings in the 45 minutes after an over-temperature spike.
    invalid = pd.Series(False, index=df.index)
    for spike in df.loc[df["temp"] > TEMP_LIMIT_C, "ts_local"]:
        invalid |= (df["ts_local"] > spike) & (df["ts_local"] <= spike + SHUTDOWN_WINDOW)

    for start, end in MAINTENANCE.get(farm_key, []):
        invalid |= (df["ts_local"] >= pd.Timestamp(start)) & (df["ts_local"] < pd.Timestamp(end))

    df = df[~invalid]

    df["ts_utc"] = (
        df["ts_local"]
        .dt.tz_localize(timezone, ambiguous="NaT", nonexistent="NaT")
        .dt.tz_convert("UTC")
    )
    df = df[(df["ts_utc"] >= DAY_START) & (df["ts_utc"] < DAY_END)]
    df = df[df["value"].notna() & (df["value"] >= 0)]

    factor = UNIT_TO_K[unit]
    if reading_type == "power":
        factor *= interval_h
    return float(df["value"].sum() * factor)


def answer() -> dict[str, int]:
    farms = pd.read_csv(f"{DATA_DIR}/farms.csv")
    farms["key"] = farms["farm_name"].str.strip().str.lower()
    registry = pd.read_csv(f"{DATA_DIR}/farm_registry.csv")
    registry["key"] = registry["farm_name"].str.strip().str.lower()
    meta = registry.merge(farms[["key", "timezone"]], on="key", how="left")

    with open(f"{DATA_DIR}/sensors_calibration.json") as f:
        calibration = json.load(f)["enterprise_platform"]["deployment_environments"][
            "system_config"
        ]["farms"]

    result = {}
    for _, row in meta.iterrows():
        farm_id = row["farm_id"].strip()
        try:
            total = farm_energy_kwh(farm_id, row["timezone"].strip(), row["key"], calibration[farm_id])
        except (FileNotFoundError, KeyError):
            total = 0.0
        result[farm_id] = int(round(total))
    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

